insert into public.news (id, sort_order, title, image_src, category, published_at, read_minutes, body) values
  ('elden-ring', 1, 'Elden Ring: Shadow of the Erdtree Expansion Gets Official Release Date', '/assets/news/elden-ring.webp', 'lanzamientos', '2025-03-30', 5, '[{"type":"p","text":"FromSoftware confirmó la fecha de lanzamiento de Shadow of the Erdtree, la expansión más grande que hizo el estudio. Llega a PC, PlayStation y Xbox, y se juega después de derrotar a Mohg, Señor de la Sangre."},{"type":"h","text":"Qué trae la expansión"},{"type":"p","text":"La Tierra de las Sombras suma un mapa nuevo, armas, hechizos y jefes. El tráiler mostró a Messmer el Empalador, uno de los semidioses de los que el juego base sólo hablaba."},{"type":"quote","text":"Es la expansión más grande que hicimos."},{"type":"p","text":"Para la comunidad de Sura, la expansión llega con un evento propio: tres noches de speedrun con premios en USDC. La inscripción abre la semana del lanzamiento."}]'::jsonb),
  ('guild-of-guardians', 2, 'Top 3 Guild of Guardians characters highlights', '/assets/home/news/guild-of-guardians.webp', 'guias', '2025-03-20', 5, '[{"type":"p","text":"Guild of Guardians tiene más de cien héroes, y elegir con cuáles armar el equipo es la mitad del juego. Estos son los tres que más se repiten entre los mejores jugadores de la comunidad."},{"type":"h","text":"Por qué estos tres"},{"type":"p","text":"Los tres cubren un rol distinto: uno aguanta el daño, otro lo reparte y el tercero cura. Juntos funcionan en casi todas las mazmorras sin tener que cambiar de estrategia."},{"type":"p","text":"Si recién empezás, conviene subir de nivel primero al que cura: es el que más partidas salva cuando el equipo todavía es débil."}]'::jsonb),
  ('cyberpunk-2077', 3, 'Cyberpunk 2077: Phantom Liberty - The Expansion That Redeems Night City', '/assets/news/cyberpunk-2077.webp', 'actualizaciones', '2025-03-20', 5, '[{"type":"p","text":"Phantom Liberty llegó junto con la actualización 2.0, que rehízo el árbol de habilidades, la policía y los combates en vehículo. Para muchos jugadores, es el Cyberpunk 2077 que se prometió en el lanzamiento."},{"type":"h","text":"Dogtown"},{"type":"p","text":"La expansión transcurre en Dogtown, un distrito nuevo con su propia historia de espionaje. Se puede jugar en cualquier momento de la partida, sin terminar la campaña principal."},{"type":"quote","text":"Night City por fin se siente viva."},{"type":"p","text":"La actualización es gratis para todos los que tienen el juego base; la expansión se compra aparte."}]'::jsonb),
  ('warzone-temporada-3', 4, 'Warzone suma un mapa nuevo para la temporada 3', '/assets/news/warzone-temporada-3.webp', 'actualizaciones', '2025-03-18', 4, '[{"type":"p","text":"La temporada 3 de Warzone llega con un mapa nuevo, más chico que los anteriores y pensado para partidas cortas de 50 jugadores."},{"type":"h","text":"Qué cambia"},{"type":"p","text":"Vuelven los contratos de recompensa y se ajustan las armas más usadas de la temporada pasada. El pase de batalla suma dos operadores nuevos."},{"type":"p","text":"En Sura, el primer torneo en el mapa nuevo abre su inscripción esta semana."}]'::jsonb),
  ('monster-hunter-wilds-actualizacion', 5, 'Monster Hunter Wilds suma un monstruo nuevo gratis', '/assets/news/monster-hunter-wilds-actualizacion.webp', 'actualizaciones', '2025-03-15', 6, '[{"type":"p","text":"Capcom publicó la primera actualización gratuita de Monster Hunter Wilds: un monstruo nuevo, una zona de caza ampliada y un evento por tiempo limitado."},{"type":"h","text":"Qué trae"},{"type":"p","text":"El monstruo llega con su propio set de armadura y armas nuevas para las catorce clases. La actualización también ajusta la dificultad de las cacerías en grupo."},{"type":"p","text":"En Sura, la misión de caza de esta semana suma el doble de puntos si el objetivo es el monstruo nuevo."}]'::jsonb),
  ('liga-ancestral-inscripciones', 6, 'La Liga Ancestral de Dota 2 abre inscripciones en Sura', '/assets/news/liga-ancestral-inscripciones.webp', 'sura', '2025-03-12', 3, '[{"type":"p","text":"Sura lanza la Liga Ancestral, su primera liga de Dota 2: cuatro semanas de series en Captains Mode y una final en vivo con casteo en español."},{"type":"h","text":"Cómo participar"},{"type":"p","text":"Los equipos se inscriben desde Eventos, con un capitán y cinco titulares. Cada serie suma Sura Points aunque no ganes, y los primeros puestos se llevan premios en USDC."},{"type":"quote","text":"Es la liga más grande que armamos con la comunidad."}]'::jsonb),
  ('marvel-rivals-temporada', 7, 'Marvel Rivals: los héroes que llegan en la nueva temporada', '/assets/news/marvel-rivals-temporada.webp', 'lanzamientos', '2025-03-10', 4, '[{"type":"p","text":"NetEase presentó la nueva temporada de Marvel Rivals, con dos héroes nuevos, un mapa y cambios en el sistema de rangos."},{"type":"h","text":"Los recién llegados"},{"type":"p","text":"Los dos héroes nuevos cubren roles que el plantel tenía flojos: uno de apoyo con curación a distancia y un vanguardia que protege a todo el equipo con escudos."},{"type":"p","text":"La Copa Rivals de Sura se juega con la temporada nueva, así que conviene practicar con los héroes antes de la inscripción."}]'::jsonb),
  ('ligas-rocket-league', 8, 'Las mejores ligas de Rocket League para arrancar', '/assets/news/ligas-rocket-league.webp', 'esports', '2025-03-08', 7, '[{"type":"p","text":"Rocket League es una de las puertas de entrada más amables a los esports: los partidos duran cinco minutos, hay rangos para todos los niveles y se juega gratis."},{"type":"h","text":"Por dónde empezar"},{"type":"p","text":"Conviene arrancar por una liga con división de principiantes y horarios fijos. Así se entrena siempre contra los mismos rivales y se nota el progreso."},{"type":"p","text":"En Sura hay dos ligas abiertas este mes, las dos con inscripción gratis y partidos de tres contra tres."}]'::jsonb),
  ('mundial-fifa-2026-mini-juego', 9, 'El Mundial FIFA 2026 llega a Sura con un mini-juego', '/assets/news/mundial-fifa-2026-mini-juego.webp', 'sura', '2025-03-05', 3, '[{"type":"p","text":"Sura suma un mini-juego de fútbol para acompañar el Mundial FIFA 2026. Cada partido ganado suma Sura Points y entradas a un sorteo."},{"type":"h","text":"El premio"},{"type":"p","text":"Entre los que jueguen durante el torneo se sortea un viaje para ver un partido del Mundial. Cuantas más partidas, más chances."}]'::jsonb),
  ('valorant-champions-equipos', 10, 'Valorant Champions Tour: los equipos a seguir', '/assets/news/valorant-champions-equipos.webp', 'esports', '2025-03-02', 6, '[{"type":"p","text":"Arranca una nueva temporada del Valorant Champions Tour y la región latinoamericana llega con varios equipos que pelean por un lugar en el torneo internacional."},{"type":"h","text":"A quién mirar"},{"type":"p","text":"Los equipos que mejor terminaron el año pasado mantuvieron a sus jugadores clave, y hay dos proyectos nuevos que armaron sus planteles con talento de la escena competitiva regional."},{"type":"p","text":"Los partidos se pueden seguir en vivo, y en Sura hay un evento de predicciones con premios para cada jornada."}]'::jsonb),
  ('ac-shadows-consejos', 11, 'Assassin''s Creed Shadows: cinco consejos para empezar', '/assets/news/ac-shadows-consejos.webp', 'guias', '2025-02-28', 5, '[{"type":"p","text":"Shadows es un juego largo y alterna entre dos protagonistas, Naoe y Yasuke. Las primeras horas definen mucho de cómo se disfruta el resto, y estos consejos ayudan a arrancar bien."},{"type":"h","text":"Lo primero"},{"type":"p","text":"Usá a Naoe para las misiones de infiltración y a Yasuke para los combates abiertos: cada uno tiene su propio árbol de habilidades y conviene mejorarlos por separado."},{"type":"p","text":"Y no ignores el escondite: mejorarlo desde temprano desbloquea aliados y bonificaciones que después hacen todo más fácil."}]'::jsonb);
